{
  "id": "RF-OBJECTION",
  "standing": "adopted",
  "selected_version": "1.0",
  "scope": "Fictional case only",
  "authority": "The fictional institution's council; adoption status is as specified.",
  "clauses": [
    {
      "id": "P1",
      "relation": "objection",
      "text": "Identifying a problem does not, solely by that act, assign responsibility for solving it to the objector."
    },
    {
      "id": "P2",
      "relation": "undertaking",
      "text": "Someone who accepted a bounded advisory task can owe further inquiry because of that undertaking, even without power to block a decision."
    },
    {
      "id": "P3",
      "relation": "control",
      "text": "Exercising actual power to block an option can create or deepen responsibilities to justify the restriction, consider its effects, and investigate proportionate alternatives."
    },
    {
      "id": "P4",
      "relation": "limits",
      "text": "Capacity, serious competing responsibilities, uncertainty, and existing permissions constrain inquiry and subsequent action. A limited obligation is not an unlimited commitment."
    },
    {
      "id": "P5",
      "relation": "unresolved_harm",
      "text": "The absence of a known alternative neither requires an unsafe option to proceed nor excuses indefinite, unreviewable blocking. The effects of delay and the existing baseline also require consideration."
    },
    {
      "id": "P6",
      "relation": "authority",
      "text": "Responsibility arising from de facto control does not legitimize that control. A duty to investigate does not itself authorize remedial actions."
    },
    {
      "id": "P7",
      "relation": "standing",
      "text": "A proposed principle is not an adopted rule merely because it is retrieved, repeated, or persuasive."
    }
  ]
}

